import pathlib,json,argparse,collections
P=argparse.ArgumentParser();P.add_argument('--work',required=True);A=P.parse_args();W=pathlib.Path(A.work);R=pathlib.Path(__file__).resolve().parents[2];a=json.load(open(R/'docs/trade-cn-v1/CN_AUDIT_121.json'));entities=json.load(open(R/'docs/trade-cn-v1/TRADE_MARKET_ENTITIES.json'));totals=json.load(open(W/'country-customs-totals.json'));observed=set(totals['observed_codes']);lookup={e['cn8']:e for e in entities};out=[]
for species in a:
 codes=[c for c in species['sowing_specific_codes']if c in observed];exact=[c for c in codes if lookup[c]['granularity']in['SPECIES_SPECIFIC','PARTIAL']and species['canonical_species_id']in lookup[c]['species_ids']];groups=[c for c in codes if lookup[c]['granularity']=='GROUP_LEVEL'];production=species['production_available'];trade=bool(exact or groups)
 status='PRODUCTION_AND_SPECIES_TRADE'if production and exact else'PRODUCTION_AND_GROUP_TRADE'if production and groups else'PRODUCTION_ONLY'if production else'TRADE_ONLY'if trade else'NEITHER'
 out.append({'species_id':species['canonical_species_id'],'common_name':species['common_name'],'botanical':species['botanical_name'],'primary_category':species['seed_category'],'production_available':production,'species_trade_available':bool(exact),'partial_species_scope':bool(exact)and species['proposed_cn_status']=='PARTIAL','group_trade_available':bool(groups),'trade_codes':codes,'status':status,'volume_allocated_to_species':False if groups and not exact else None,'interpretation':'NOT_PERFORMED'})
counts=dict(collections.Counter(s['status']for s in out));assert len(out)==121 and sum(counts.values())==121
(W/'PRODUCTION_TRADE_INTERSECTION.json').write_text(json.dumps({'counts':counts,'species':out,'scope':'Group membership is not species-measured volume.'},indent=2)+'\n');print(counts)
